def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    for c in ['species', 'island', 'sex']:
        if c in df.columns:
            df[c] = df[c].astype('string').str.strip()
    df['species'] = df['species'].replace({'Adeile': 'Adelie'})
    df['sex'] = df['sex'].replace({'FEMALE': 'female', 'MALE': 'male'})
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = float('nan')
    df = df.dropna(subset=['species', 'body_mass_g'])
    return df

def answer(df):
    g = df.groupby('species')['body_mass_g'].mean()
    return {k: float(v) for k, v in g.items() if pd.notna(v)}
